  const makeSentences = (materialId, rows, kind) => rows.map((row,i)=>({id:`${materialId}-s${i+1}`,materialId,orderIndex:i,textEn:row[0],textZh:row[1],audioKind:kind,audioPath:kind==='original'?`data/listening-sentences/${String(i+1).padStart(2,'0')}.wav`:null}));
