  function icon(name){return `<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name]}"></path></svg>`}
  function openHandleDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open(HANDLE_DB,1);request.onupgradeneeded=()=>request.result.createObjectStore(HANDLE_STORE);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
  async function storedDirectoryHandle(value){const db=await openHandleDb();return new Promise((resolve,reject)=>{const tx=db.transaction(HANDLE_STORE,value?'readwrite':'readonly'),store=tx.objectStore(HANDLE_STORE),request=value?store.put(value,HANDLE_KEY):store.get(HANDLE_KEY);request.onsuccess=()=>resolve(value||request.result||null);request.onerror=()=>reject(request.error);tx.oncomplete=()=>db.close()})}
  async function normalizeIeltsRoot(handle){if(handle.name==='IELTS')return handle;try{return await handle.getDirectoryHandle('IELTS')}catch{throw new Error('请选择 data 文件夹，或直接选择其中的 IELTS 文件夹')}}
  async function restoreDataDirectory(){if(!('indexedDB'in window))return;try{const handle=await storedDirectoryHandle();if(!handle)return;importedIeltsRoot=handle;dataSourceState=await handle.queryPermission({mode:'read'})==='granted'?'connected':'permission';if(location.hash==='#library'||!location.hash)renderLibraryV12()}catch{dataSourceState='project'}}
  async function connectDataDirectory(){if(!window.showDirectoryPicker){toast('当前浏览器不支持记住文件夹，请使用 Chrome 或 Edge');return}const button=$('#connectDataFolder');if(button){button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='正在选择…'}try{const selected=await window.showDirectoryPicker({id:'ielts-study-data',mode:'read'}),root=await normalizeIeltsRoot(selected);importedAudioUrls.forEach(URL.revokeObjectURL);importedAudioUrls.clear();importedIeltsRoot=root;dataSourceState='connected';await storedDirectoryHandle(root);renderLibraryV12();toast(`已连接 ${root.name} 文件夹`)}catch(error){if(error?.name!=='AbortError')toast(error.message||'无法读取所选文件夹');if(location.hash==='#library'||!location.hash)renderLibraryV12()}}
  async function importedFile(path){if(!importedIeltsRoot)return null;const permission=await importedIeltsRoot.queryPermission({mode:'read'});if(permission!=='granted'){dataSourceState='permission';return null}const relative=path.replace(/^\.?\/?data\/IELTS\//,'').split('/').filter(Boolean);let directory=importedIeltsRoot;for(const segment of relative.slice(0,-1))directory=await directory.getDirectoryHandle(segment);return (await directory.getFileHandle(relative.at(-1))).getFile()}
  async function readDataText(path){if(importedIeltsRoot){try{const file=await importedFile(path);if(file)return file.text()}catch{}}const response=await fetch(path,{cache:'no-store'});if(!response.ok)throw new Error(`无法读取 ${path}`);return response.text()}
  async function resolveAudioPath(path){if(!importedIeltsRoot)return path;if(importedAudioUrls.has(path))return importedAudioUrls.get(path);try{const file=await importedFile(path);if(!file)return path;const url=URL.createObjectURL(file);importedAudioUrls.set(path,url);return url}catch{return path}}
  function load(){try{const saved=JSON.parse(localStorage.getItem(STORE_KEY));return saved?.version==='1.1'?saved:structuredClone(seed)}catch{return structuredClone(seed)}}
  function removeDemoMaterials(value){const ids=new Set(['listen-riverside','read-green-cities']),sentenceIds=new Set(value.sentences.filter(s=>ids.has(s.materialId)).map(s=>s.id)),vocabularyIds=new Set(value.vocabulary.filter(v=>sentenceIds.has(v.sourceSentenceId)).map(v=>v.id));value.materials=value.materials.filter(m=>!ids.has(m.id));value.sentences=value.sentences.filter(s=>!ids.has(s.materialId));value.vocabulary=value.vocabulary.filter(v=>!vocabularyIds.has(v.id));value.occurrences=value.occurrences.filter(o=>!vocabularyIds.has(o.vocabularyItemId));ids.forEach(id=>delete value.progress[id]);if(ids.has(value.currentMaterialId))value.currentMaterialId=value.materials[0]?.id||'';return value}
  function save(){localStorage.setItem(STORE_KEY,JSON.stringify(state)); updateCount()}
  function blankDictation(sentenceId,practiceContext='study'){return {sentenceId,practiceContext,draftText:'',firstAttemptText:'',submitted:false,skipped:false,comparing:false,attemptId:'',hintLevel:0,predictedRecall:null}}
  function loadDictation(){try{return JSON.parse(localStorage.getItem(DICTATION_KEY))||blankDictation('')}catch{return blankDictation('')}}
  function ensureDictation(){const id=currentSentence().id;if(dictation.sentenceId!==id){dictation=blankDictation(id);saveDictation()}if(!dictation.practiceContext)dictation.practiceContext='study';return dictation}
