  function esc(s=''){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
  function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
  function source(material){return material.description||`${material.collection} · Test ${material.testNo} · ${material.skill==='listening'?'Listening Part':'Reading Passage'} ${material.sectionNo}`}
  function currentMaterial(){return state.materials.find(m=>m.id===state.currentMaterialId)||state.materials[0]}
