  function radioUnit(book,test,part){const audioPath=part?localAudioPath(book,test,part):localFullTestAudioPath(book,test),label=part?`Part ${part}`:`完整 Test ${test}`;return `<div class="material-row audio-ready"><div><strong>${label}</strong><span>Listening</span></div><p>原始音频已就绪 · AI英文转写</p><button class="secondary-btn open-radio-transcript" data-book="${book}" data-test="${test}" ${part?`data-part="${part}"`:''}>载入英文原文</button></div>`}
