  function renderLocalLrcCollection(){const groups=localSeries.map(([name,episodes])=>`<details class="test-group"><summary><strong>${esc(name)}</strong><span>${episodes.length} 组 · Audio + LRC</span></summary><div class="unit-section local-episode-grid">${episodes.map(index=>`<button class="secondary-btn open-local-episode" data-series="${esc(name)}" data-index="${index}">${String(index).padStart(2,'0')} · 逐句学习</button>`).join('')}</div></details>`).join('');$('#app').innerHTML=`<section class="app-page"><button class="secondary-btn back-library">${icon('arrowLeft')}<span>返回资料库</span></button><div class="collection-summary"><div><p class="eyebrow">LOCAL AUDIO + LRC</p><h2>158 组可逐句学习材料</h2><p>LRC 时间轴会按英文句末标点合并，播放时从完整句首到下一句开始。</p></div><span class="waiting-pill">Ready for sentence learning</span></div><div class="test-list">${groups}</div></section>`;$('.back-library').onclick=()=>location.hash='library';$$('.open-local-episode').forEach(b=>b.onclick=()=>loadLocalEpisode(b.dataset.series,Number(b.dataset.index),b))}
  async function loadLocalEpisode(series,index,button){const displayNumber=String(index).padStart(2,'0'),fileNumber=series==='海洋岛屿'?String(index):displayNumber,base=`data/IELTS/英语听力 - ${series} ${fileNumber}`,originalLabel=button.textContent;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='正在载入…';try{const rows=parseLrc(await readDataText(`${base}.lrc`)),id=`local-${series}-${displayNumber}`,material={id,collection:'英语听力逐句资料',title:`${series} ${displayNumber}`,testNo:index,skill:'listening',sectionNo:1,audioKind:'original',audioPath:`${base}.mp3`,description:`${series} · 第 ${displayNumber} 集`};state.materials=state.materials.filter(m=>m.id!==id);state.sentences=state.sentences.filter(s=>s.materialId!==id);state.materials.push(material);state.sentences.push(...rows.map((row,i)=>({id:`${id}-s${i+1}`,materialId:id,orderIndex:i,textEn:row.text,textZh:'',audioKind:'original',audioPath:material.audioPath,startMs:row.startMs,endMs:row.endMs})));state.progress[id]=state.progress[id]||{currentSentenceIndex:0,completedSentenceCount:0};state.currentMaterialId=id;save();location.hash='material'}catch{button.disabled=false;button.removeAttribute('aria-busy');button.textContent=originalLabel;toast(dataSourceState==='permission'?'请先在资料库重新授权 data 文件夹':'无法读取这组 LRC 文件')}}
  function parseLrc(text){const lines=text.split(/\r?\n/).map(line=>{const match=line.match(/^\[(\d+):(\d+(?:\.\d+)?)\](.*)$/);return match?{time:(Number(match[1])*60+Number(match[2]))*1000,text:match[3].trim()}:null}).filter(row=>row&&row.text);const sentences=[],buffer=[];for(const line of lines){buffer.push(line);if(/[.!?][”’"']?$/.test(line.text))flush()}flush();function flush(){if(!buffer.length)return;sentences.push({startMs:buffer[0].time,endMs:null,text:buffer.map(x=>x.text).join(' ').replace(/\s+([,.;!?])/g,'$1')});buffer.length=0}return sentences.map((sentence,i)=>({...sentence,endMs:sentences[i+1]?.startMs||null}))}
