  function renderMaterial(){const m=currentMaterial(),ss=currentSentences(),p=state.progress[m.id];setHead(m.skill.toUpperCase(),m.title);$('#app').innerHTML=`<section class="app-page"><button class="secondary-btn" id="backLibrary">${icon('arrowLeft')}<span>返回资料库</span></button><div class="panel import-card" style="margin-top:18px"><p class="eyebrow">${m.skill==='listening'?'ORIGINAL AUDIO + TIMESTAMPS':'SENTENCE TTS'}</p><h2>${esc(m.title)}</h2><p>${esc(source(m))}</p><div class="section-head"><span>${ss.length} 个 Sentence</span><span>${p.completedSentenceCount} 已访问</span></div><progress max="${ss.length}" value="${p.completedSentenceCount}"></progress><div class="card-footer"><span class="meta">上次位置：第 ${p.currentSentenceIndex+1} 句</span><button class="primary-btn" id="startMaterial">${p.completedSentenceCount?'继续学习':'开始学习'}</button></div></div></section>`;$('#backLibrary').onclick=()=>location.hash='library';$('#startMaterial').onclick=()=>location.hash='study'}
  function compareDictation(actualText,expectedText){return learning.compare(actualText,expectedText)}
