  function recordCurrentAttempt(d,skipped=false){if(d.attemptId)return;const s=currentSentence(),id=crypto.randomUUID();learning.recordAttempt(state,{id,sentenceId:s.id,actualText:d.firstAttemptText,expectedText:s.textEn,hintLevel:d.hintLevel||0,practiceContext:d.practiceContext||'study',predictedRecall:d.predictedRecall,skipped});d.attemptId=id;save()}
  function completeDictation(){const input=$('#dictationInput'),d=ensureDictation();if(!Number.isFinite(d.predictedRecall)){toast('请先判断自己有多确定');$('input[name="recallConfidence"]')?.focus();return}d.draftText=input?.value||'';d.firstAttemptText=d.draftText;d.submitted=true;d.skipped=false;d.comparing=false;recordCurrentAttempt(d);saveDictation();renderStudy();setTimeout(()=>$('#showEnglish')?.focus(),0)}
